<div class="d-flex flex-wrap gap-2 justify-content-between align-items-center mb-3"><div><a href="<?= url('/quotations') ?>" class="text-decoration-none">← Quotations</a><p class="text-secondary mb-0"><?= e($quote['customer_name']) ?> · <?= e($quote['quotation_date']) ?></p></div><div class="d-flex gap-2"><button class="btn btn-outline-secondary collab-btn" data-entity="quotation" data-id="<?= $quote['id'] ?>"><i class="bi bi-chat-left-text"></i> Notes & Docs</button><a class="btn btn-outline-secondary" target="_blank" href="<?= url('/print/quotation/'.$quote['id']) ?>"><i class="bi bi-printer"></i> Print/PDF</a><?php if($quote['status']==='Approved'): ?><button class="btn btn-primary ajax-action" data-url="<?= url('/quotations/'.$quote['id'].'/convert') ?>">Create Job</button><?php endif; ?></div></div>
<div class="row g-3"><div class="col-lg-8"><div class="card-panel"><div class="panel-head"><div><h3>Quotation Items</h3><p><?= e($quote['quotation_number']) ?></p></div><span class="status-badge <?= $quote['status']==='Approved'?'success':'' ?>"><?= e($quote['status']) ?></span></div><div class="table-responsive"><table class="table"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th class="text-end">Price</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['description']) ?><small class="d-block text-secondary"><?= e($i['item_type']) ?></small></td><td><?= e($i['quantity']) ?></td><td><?= e($i['unit']) ?></td><td class="text-end"><?= e(money($i['unit_price'])) ?></td><td class="text-end"><?= e(money($i['line_total'])) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="4" class="text-end">Subtotal</th><th class="text-end"><?= e(money($quote['subtotal'])) ?></th></tr><tr><th colspan="4" class="text-end">Discount</th><th class="text-end">-<?= e(money($quote['discount'])) ?></th></tr><tr><th colspan="4" class="text-end">Tax</th><th class="text-end"><?= e(money($quote['tax'])) ?></th></tr><tr><th colspan="4" class="text-end">Grand Total</th><th class="text-end fs-5"><?= e(money($quote['grand_total'])) ?></th></tr></tfoot></table></div></div></div><div class="col-lg-4"><div class="card-panel mb-3"><h3 class="h6">Workflow</h3><form class="ajax-form" action="<?= url('/quotations/'.$quote['id'].'/status') ?>" method="post"><?= csrf_field() ?><label class="form-label">Status</label><select class="form-select mb-2" name="status"><?php foreach(['Draft','Internal Review','Sent','Viewed','Approved','Rejected','Expired'] as $st): ?><option <?= $quote['status']===$st?'selected':'' ?>><?= e($st) ?></option><?php endforeach; ?></select><button class="btn btn-outline-primary w-100">Update Status</button></form><?php if($quote['status']!=='Approved'): ?><hr><form class="ajax-form" method="post" action="<?= url('/quotations/'.$quote['id'].'/approve') ?>"><?= csrf_field() ?><input class="form-control mb-2" name="customer_name" placeholder="Approver name" value="<?= e($quote['customer_name']) ?>"><input class="form-control mb-2" name="customer_email" placeholder="Approver email" value="<?= e($quote['customer_email']??'') ?>"><button class="btn btn-success w-100">Approve Quotation</button></form><?php endif; ?></div><div class="card-panel"><h3 class="h6">Approval History</h3><?php if(!$approvals): ?><p class="text-secondary small">No approval record.</p><?php endif; ?><?php foreach($approvals as $a): ?><div class="timeline-item"><strong><?= e($a['action']) ?></strong><small><?= e($a['customer_name']) ?> · <?= e($a['approved_at']) ?></small></div><?php endforeach; ?></div></div></div>
